defmodule Indexer.Fetcher.Fluent.BridgeTest do
  use ExUnit.Case, async: true

  alias Indexer.Fetcher.Fluent.Bridge

  test "parses legacy SentMessage log payload with messageHash in data" do
    event = %{
      first_topic: "0x7b397c6ce16a73396390bf270a2021417ca4d97f44e82cdce3f5eb750fd34134",
      second_topic: "0x0000000000000000000000008976ca4e0c8467097da675399fb7db454a1b56dd",
      third_topic: "0x0000000000000000000000008976ca4e0c8467097da675399fb7db454a1b56dd",
      transaction_hash: "0xdeadbeef",
      block_number: "0xa2dea6",
      data:
        ""
    }

    parsed = Bridge.sent_message_event_parse(event)

    assert parsed.sender == "0x8976ca4e0c8467097da675399fb7db454a1b56dd"
    assert parsed.target == "0x8976ca4e0c8467097da675399fb7db454a1b56dd"
    assert parsed.value == 1_000_000_000_000_000
    assert parsed.fee == nil
    assert parsed.chain_id == 11_155_111
    assert parsed.source_block_number == 10_673_830
    assert parsed.valid_until_block_number == 10_673_830
    assert parsed.nonce == 0
    assert parsed.message_hash == "0xd510a8858b7e9ff4866ae1acb924cec45548a18d71a05fb2e2b596a5c31075ea"
  end
end
